  const string xaml="<Window xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' Title='应用与规则 · by CraZyX' Width='980' Height='700' MinWidth='820' MinHeight='600' WindowStartupLocation='CenterOwner' Background='#161D25' Foreground='#DFEAF2' FontFamily='Microsoft YaHei UI' FontSize='13'><Grid Background='#161D25'><Grid Margin='24'><Grid.RowDefinitions><RowDefinition Height='Auto'/><RowDefinition Height='Auto'/><RowDefinition Height='*'/><RowDefinition Height='Auto'/></Grid.RowDefinitions><TextBlock x:Name='Heading' FontSize='24' FontWeight='SemiBold' Foreground='#39C5BB' Text='应用发现与规则库'/><TextBlock x:Name='LibraryState' Grid.Row='1' Margin='0,10,0,16' Foreground='#A7BFCD'/><TabControl Foreground='#DFEAF2' Grid.Row='2' Background='#1D2933' BorderBrush='#344651'><TabItem Header='规则更新'><ScrollViewer VerticalScrollBarVisibility='Auto'><StackPanel Margin='18'><TextBlock Text='HTTPS 规则文件地址' FontSize='15' FontWeight='SemiBold'/><TextBox x:Name='UpdateUrl' Margin='0,10,0,12' Height='34' Background='#25333E' Foreground='#DFEAF2' BorderBrush='#45616C' Padding='8'/><CheckBox x:Name='Automatic' Content='每 7 天自动检查一次（需先填写地址）' Margin='0,0,0,14'/><WrapPanel><Button x:Name='Save' Content='保存设置' Margin='0,0,9,9'/><Button x:Name='Check' Content='检查更新' Margin='0,0,9,9' Background='#39C5BB' Foreground='#083F3A'/><Button x:Name='Import' Content='本地导入' Margin='0,0,9,9'/><Button x:Name='Export' Content='导出当前规则' Margin='0,0,9,9'/><Button x:Name='Rollback' Content='回退上一版' Margin='0,0,9,9'/></WrapPanel><TextBlock Text='云更新只接受已验证发布者签名的规则包。未签名本地规则需确认导入；外部规则只供高级自选。' Foreground='#E4BE81' TextWrapping='Wrap' Margin='0,8,0,18'/><TextBlock Text='便携 / 自定义软件目录' FontSize='15' FontWeight='SemiBold'/><ListBox x:Name='Portable' Background='#202D37' Foreground='#CFDFEB' BorderBrush='#344651' Height='100' Margin='0,10,0,10'/><WrapPanel><Button x:Name='AddPortable' Content='添加目录' Margin='0,0,9,9'/><Button x:Name='RemovePortable' Content='移除所