indow>";
  string markup=xaml.Replace("<TextBlock Text='HTTPS 规则文件地址'","<TextBlock Text='规则来源' FontSize='15' FontWeight='SemiBold'/><ComboBox x:Name='RuleProvider' Margin='0,10,0,16' Height='36'/><TextBlock Text='HTTPS 规则文件地址'").Replace("<TextBlock Text='云更新只接受", "<TextBlock x:Name='SourceHint' Text='云更新只接受").Replace("<Button x:Name='Rollback'", "<Button x:Name='Compatibility' Content='兼容报告' Margin='0,0,9,9'/><Button x:Name='Rollback'");
  var w=(Window)XamlReader.Parse(markup);w.Owner=owner;w.Resources=owner.Resources;Func<string,TextBox> text=n=>(TextBox)w.FindName(n);Func<string,Button> button=n=>(Button)w.FindName(n);
  var store=new RuleStore();var communityStore=new Winapp2Store();var provider=(ComboBox)w.FindName("RuleProvider");var state=(TextBlock)w.FindName("LibraryState");var hint=(TextBlock)w.FindName("SourceHint");var status=(TextBlock)w.FindName("Status");var automatic=(CheckBox)w.FindName("Automatic");var portable=(ListBox)w.FindName("Portable");var apps=(ListBox)w.FindName("Apps");
  Action refresh=()=>{if(settings.UseWinapp2){var pack=communityStore.Current();state.Text="Winapp2 "+pack.Version+" · "+pack.Entries.Count+" 条定义 · "+pack.Origin;hint.Text="社区规则未签名，默认不选，支持的文件项仅供高级自选并先备份。密码、Cookie、会话、配置、数据库及任意社区注册表删除保留；兼容报告列出支持与保留原因。";}else{var pack=store.Current();state.Text="规则库 "+pack.Pack.Version+" · "+pack.Pack.Rules.Count+" 条应用规则 · "+pack.Trust;hint.Text="JSON 云更新只接受发布者签名包；未签名本地规则需确认导入，外部规则只供高级自选。";}portable.ItemsSource=settings.PortableDirectories.ToArray();button("Compatibility").Visibility=settings.UseWinapp2?Visibility.Visible:Visibility.Collapsed;};
  provider.ItemsSource=new[]{"Winapp2.ini · 社区规则","签名 JSON · 自定义规则"};provider.SelectedIndex=settings.UseWinapp2?0:1;
  text("UpdateUrl").Text=settings.UseWinapp2?Winapp2Store.Url:settings.UpdateUrl;text("UpdateUrl").IsReadOnly=settings.UseWinapp2;automatic.Content="每 7 天自动检查一次";automatic.IsChecked=settings.AutomaticUpdates;
  provider.SelectionChanged+=(s,e)=>{settings.UseWinapp2=provider.SelectedIndex==0;text("UpdateUrl").Text=settings.UseWinapp2?Winapp2Store.Url:settings.UpdateUrl;text("UpdateUrl").IsReadOnly=settings.UseWinapp2;if(!settings.UseWinapp2&&String.IsNullOrWhiteSpace(settings.UpdateUrl))automatic.IsChecked=false;refresh();changed();status.Text="保存设置后，重新扫描使用所选来源。";};refresh();
  text("RecoveryPath").Text=String.IsNullOrEmpty(settings.RecoveryDirectory)?FileRecovery.DefaultDirectory():settings.RecoveryDirectory;var identities=discovery==null?new List<ApplicationIdentity>():discovery.Applications;apps.ItemsSource=identities;text("AppSearch").ToolTip="搜索应用名、发行商或程序路径";text("AppSearch").TextChanged+=(s,e)=>apps.ItemsSource=identities.Where(a=>a.SearchText.IndexOf(text("AppSearch").Text,StringComparison.OrdinalIgnoreCase)>=0).ToList();apps.SelectionChanged+=(s,e)=>{var a=apps.SelectedItem as ApplicationIdentity;text("AppEvidence").Text=a==null?"":RuleStore.Describe(a)+"\n产品："+a.Product+"\n公司："+a.Company+"\n安装目录："+a.InstallDirectory;};if(identities.Count==0)text("AppEvidence").Text="手动开始扫描后会显示应用发现结果。";
  Action save=()=>{if(!settings.UseWinapp2){string url=text("UpdateUrl").Text.Trim();Uri address;if(url.Length>0&&(!Uri.TryCreate(url,UriKind.Absolute,out address)||address.Scheme!="https"||!String.IsNullOrEmpty(address.UserInfo)))throw new InvalidDataException("请输入 HTTPS 规则地址");if(automatic.IsChecked==true&&url.Length==0)throw new InvalidDataException("自动检查需先填写发布地址");settings.UpdateUrl=url;}settings.AutomaticUpdates=automatic.IsChecked==true;settings.Save();};button("Save").Click+=(s,e)=>{try{save();changed();status.Text="设置已保存，重新扫描后生效。";}catch(Exception ex){status.Text=ex.Message;}};
  CancellationTokenSource updateStop=null;bool updating=false,restoring=false;button("Check").Click+=async(s,e)=>{if(updating){updateStop.Cancel();return;}try{save();bool ini=settings.UseWinapp2;string url=settings.UpdateUrl;if(!ini&&String.IsNullOrWhiteSpace(url)){status.Text="尚未配置 JSON 地址，可先导入本地规则包。";return;}updating=true;updateStop=new CancellationTokenSource();provider.IsEnabled=button("Import").IsEnabled=button("Rollback").IsEnabled=false;button("Check").Content="取消更新";status.Text=ini?"从指定 Winapp2 仓库下载并检查格式…":"下载并验证发布者签名…";await Task.Run(()=>{if(ini)communityStore.Update(updateStop.Token);else store.Update(url,updateStop.Token);});refresh();changed();status.Text="当前规则已就绪，重新扫描后生效。";}catch(Exception ex){status.Text="更新未应用："+ex.Message;}finally{updating=false;provider.IsEnabled=button("Import").IsEnabled=button("Rollback").IsEnabled=true;button("Check").Content="检查更新";if(updateStop!=null)updateStop.Dispose();}};
  button("Import").Click+=(s,e)=>{var d=new OpenFileDialog{Filter="规则文件 (*.ini;*.json)|*.ini;*.json|Winapp2 (*.ini)|*.ini|JSON (*.json)|*.json",Title="导入应用清理规则"};if(d.ShowDialog(w)!=true)return;try{bool ini=Path.GetExtension(d.FileName).Equals(".ini",StringComparison.OrdinalIgnoreCase);if(new FileInfo(d.FileName).Length>(ini?Winapp2Store.MaxBytes:RuleStore.MaxBytes))throw new InvalidDataException("规则包过大");string raw=File.ReadAllText(d.FileName),description;if(ini){var parsed=Winapp2Parser.Parse(raw);description="Winapp2 "+parsed.Version+" / "+parsed.Entries.Count+" 条定义（社区未签名）。\n"+Winapp2Adapter.Analyze(parsed,Winapp2Environment.Windows()).Summary+"。\n支持项目默认不选，只供高级自选并先备份。";}else{var parsed=store.Read(raw,true);description=parsed.Pack.Version+" / "+parsed.Pack.Rules.Count+" 条规则，"+parsed.Trust+"。\n只供高级自选。";}if(MessageBox.Show(w,"导入 "+description+"\n重新扫描后生效。","检查规则来源",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;if(ini)communityStore.Import(raw);else store.Import(raw,true);settings.UseWinapp2=ini;provider.SelectedIndex=ini?0:1;settings.Save();refresh();changed();status.Text="导入完成。";}catch(Exception ex){status.Text="未导入："+ex.Message;}};
  button("Export").Click+=(s,e)=>{var d=new SaveFileDialog{Filter=settings.UseWinapp2?"INI (*.ini)|*.ini":"JSON (*.json)|*.json",FileName=settings.UseWinapp2?"Winapp2.ini":"ClearSpace-rules.json"};if(d.ShowDialog(w)==true)try{File.WriteAllText(d.FileName,settings.UseWinapp2?communityStore.Current().Raw:store.Current().Raw,new System.Text.UTF8Encoding(true));status.Text="当前规则已导出。";}catch(Exception ex){status.Text=ex.Message;}};
  button("Compatibility").Click+=(s,e)=>{var d=new SaveFileDialog{Filter="兼容报告 (*.txt)|*.txt",FileName="Winapp2-兼容报告.txt"};if(d.ShowDialog(w)==true)try{var pack=communityStore.Current();var report=Winapp2Adapter.Analyze(pack,Winapp2Environment.Windows());File.WriteAllLines(d.FileName,new[]{"Winapp2 "+pack.Version,"来源："+Winapp2Store.Url,report.Summary,"REMOVESELF 适配为清空允许的文件，保留目录；RegKey 只解析、展示，不执行。"}.Concat(report.Lines),new System.Text.UTF8Encoding(true));status.Text="兼容报告已导出。";}catch(Exception ex){status.Text=ex.Message;}};
  button("Rollback").Click+=(s,e)=>{try{if(settings.UseWinapp2)communityStore.Rollback();else store.Rollback();refresh();changed();status.Text="已回退，重新扫描后生效。";}catch(Exception ex){status.Text=ex.Message;}};
  button("AddPortable").Click+=(s,e)=>{using(var d=new System.Windows.Forms.FolderBrowserDialog{Description="选择便携或自定义安装目录"})if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK){if(!settings.PortableDirectories.Contains(d.SelectedPath,StringComparer.OrdinalIgnoreCase))settings.PortableDirectories.Add(d.SelectedPath);settings.Save();refresh();status.Text="目录已添加，下次手动扫描时检查。";}};button("RemovePortable").Click+=(s,e)=>{var selected=portable.SelectedItem as string;if(selected!=null){settings.PortableDirectories.Remove(selected);settings.Save();refresh();}};
  button("ChooseRecovery").Click+=(s,e)=>{using(var d=new System.Windows.Forms.FolderBrowserDialog{Description="选择文件备份保存目录；其他盘可释放 C 盘空间"})if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK)text("RecoveryPath").Text=d.SelectedPath;};button("SaveRecovery").Click+=(s,e)=>{try{string p=Path.GetFullPath(text("RecoveryPath").Text);if(p.StartsWith("\\\\")||!Directory.Exists(p)||!Engine.SafeAncestors(Path.Combine(p,"probe")))throw new IOException("请选择可验证的本地现有目录");settings.RecoveryDirectory=p;settings.Save();changed();status.Text="备份位置已保存。";}catch(Exception ex){status.Text=ex.Message;}};
  button("RestoreFiles").Click+=async(s,e)=>{var d=new OpenFileDialog{Filter="澄净文件备份 (*.csbackup)|*.csbackup",Title="选择文件备份索引"};if(d.ShowDialog(w)!=true)return;if(MessageBox.Show(w,"恢复本机、本账户的文件备份，已有文件保留。", "恢复文件",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;restoring=true;button("RestoreFiles").IsEnabled=button("Purge").IsEnabled=false;status.Text="正在校验并恢复文件…";try{int restored=await Task.Run(()=>FileRecovery.Restore(d.FileName));status.Text="已恢复 "+restored+" 个文件；现有文件未覆盖。";}catch(Exception ex){status.Text="恢复停止："+ex.Message;}finally{restoring=false;button("RestoreFiles").IsEnabled=button("Purge").IsEnabled=true;}};
  button("Purge").Click+=(s,e)=>{var d=new OpenFileDialog{Filter="澄净文件备份 (*.csbackup)|*.csbackup",Title="选择要清空的备份"};if(d.ShowDialog(w)!=true)return;try{var entries=FileRecovery.Read(d.FileName);if(MessageBox.Show(w,"永久删除该批 "+entries.Count+" 个备份文件。此后不能从该备份恢复。", "清空备份",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;FileRecovery.Purge(d.FileName);status.Text="该批备份已清空。";}catch(Exception ex){status.Text=ex.Message;}};
  var tabs=FindTabs((DependencyObject)w.Content);if(preview!=null){if(tabs!=null)tabs.SelectedIndex=previewTab;w.ShowInTaskbar=false;w.ShowActivated=false;w.WindowStartupLocation=WindowStartupLocation.Manual;w.Left=-10000;w.Top=-10000;w.Loaded+=(s,e)=>w.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.ContextIdle,new Action(()=>{if(previewTab==1&&apps.Items.Count>0)apps.SelectedIndex=0;App.Render(w,preview);w.Close();}));}
  w.Closing+=(s,e)=>{if(updating){e.Cancel=true;updateStop.Cancel();status.Text="正在取消更新…";}if(restoring){e.Cancel=true;status.Text="正在恢复文件，请完成后关闭。";}};w.ShowDialog();
 }
 static TabControl FindTabs(DependencyObject node){var tabs=node as TabControl;if(tabs!=null)return tabs;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(node);i++){var found=FindTabs(System.Windows.Media.VisualTreeHelper.GetChild(node,i));if(found!=null)return found;}return null;}
